455: int32_t uniform_random(int32_t minNumber, int32_t maxNumber) {
456: 	static std::uniform_int_distribution<int32_t> uniformRand;
457: 	if (minNumber == maxNumber) {
458: 		return minNumber;
459: 	}
460: 	if (minNumber > maxNumber) {
461: 		std::swap(minNumber, maxNumber);
462: 	}
463: 	return uniformRand(getRandomGenerator(), std::uniform_int_distribution<int32_t>::param_type(minNumber, maxNumber));
