466: int32_t normal_random(int32_t minNumber, int32_t maxNumber) {
467: 	static std::normal_distribution<float> normalRand(0.5f, 0.25f);
468: 	float v;
469: 	do {
470: 		v = normalRand(getRandomGenerator());
471: 	} while (v < 0.0 || v > 1.0);
472: 
473: 	auto &&[a, b] = std::minmax(minNumber, maxNumber);
474: 	return a + std::lround(v * (b - a));

